    34	    public String formatDocument(Document document) {
    35	        StringBuilder sb = new StringBuilder();
    36	        sb.append(String.format("%s nº %d%n", document.getTitle(), document.getReservationId()));
    37	        sb.append(String.format("Hóspede: %s (CPF %s)%n", document.getGuestName(), formatCpf(document.getGuestCpf())));
    38	        sb.append(String.format("Quarto: %d (%s)%n", document.getRoomNumber(), document.getRoomType()));
    39	        sb.append(String.format("Entrada: %s | Saída: %s | %d %s%n",
    40	            formatDate(document.getCheckIn()),
    41	            formatDate(document.getCheckOut()),
    42	            document.getNights(),
    43	            document.getNights() == 1 ? "diária" : "diárias"));
    44	        sb.append(String.format("Diárias: %s%n", formatMoney(document.getSubtotal())));
    45	
    46	        if (document.getDiscount().compareTo(java.math.BigDecimal.ZERO) > 0) {
    47	            sb.append(String.format("Desconto: %s%n", formatMoney(document.getDiscount())));
    48	        }
    49	
    50	        sb.append(String.format("Total: %s", formatMoney(document.getTotal())));
    51	
    52	        return sb.toString();
    53	    }
    54	
    55	    private String formatCpf(String cpf) {
    56	        if (cpf.length() == 11) {
    57	            return String.format("%s.%s.%s-%s",
    58	                cpf.substring(0, 3),
    59	                cpf.substring(3, 6),
    60	                cpf.substring(6, 9),
    61	                cpf.substring(9, 11));
    62	        }
    63	        return cpf;
    64	    }
    65	
    66	    private String formatDate(java.time.LocalDate date) {
    67	        return String.format("%02d/%02d/%04d", date.getDayOfMonth(), date.getMonthValue(), date.getYear());
    68	    }
    69	
    70	    private String formatMoney(java.math.BigDecimal amount) {
    71	        return String.format("R$ %,.2f", amount).replace(',', 'X').replace('.', ',').replace('X', '.');
    72	    }
    73	}
