     1	package com.pousada.service;
     2	
     3	import com.pousada.domain.RatePlan;
     4	import com.pousada.domain.Room;
     5	
     6	import java.math.BigDecimal;
     7	import java.math.RoundingMode;
     8	import java.time.LocalDate;
     9	import java.time.Month;
    10	
    11	public class PriceCalculator {
    12	    private static final BigDecimal HIGH_SEASON_MULTIPLIER = new BigDecimal("1.20");
    13	    private static final BigDecimal NON_REFUNDABLE_DISCOUNT = new BigDecimal("0.15");
    14	
    15	    public BigDecimal calculateNightPrice(Room room, LocalDate date) {
    16	        BigDecimal basePrice = room.getNightlyRate();
    17	        if (isHighSeason(date)) {
    18	            return basePrice.multiply(HIGH_SEASON_MULTIPLIER).setScale(2, RoundingMode.HALF_EVEN);
    19	        }
    20	        return basePrice;
    21	    }
    22	
    23	    public BigDecimal calculateSubtotal(Room room, LocalDate checkIn, LocalDate checkOut) {
    24	        BigDecimal subtotal = BigDecimal.ZERO;
    25	        LocalDate current = checkIn;
    26	
    27	        while (current.isBefore(checkOut)) {
    28	            BigDecimal nightPrice = calculateNightPrice(room, current);
    29	            subtotal = subtotal.add(nightPrice);
    30	            current = current.plusDays(1);
    31	        }
    32	
    33	        return subtotal.setScale(2, RoundingMode.HALF_EVEN);
    34	    }
    35	
    36	    public BigDecimal calculateDiscount(BigDecimal subtotal, RatePlan ratePlan) {
    37	        if (ratePlan == RatePlan.NON_REFUNDABLE) {
    38	            return subtotal.multiply(NON_REFUNDABLE_DISCOUNT).setScale(2, RoundingMode.HALF_EVEN);
    39	        }
    40	        return BigDecimal.ZERO;
    41	    }
    42	
    43	    public BigDecimal calculateTotal(BigDecimal subtotal, BigDecimal discount) {
    44	        return subtotal.subtract(discount).setScale(2, RoundingMode.HALF_EVEN);
    45	    }
    46	
    47	    private boolean isHighSeason(LocalDate date) {
    48	        Month month = date.getMonth();
    49	        int day = date.getDayOfMonth();
    50	
    51	        if (month == Month.JULY) {
    52	            return true;
    53	        }
    54	
    55	        if (month == Month.DECEMBER && day >= 15) {
    56	            return true;
    57	        }
    58	
    59	        if (month == Month.JANUARY || month == Month.FEBRUARY) {
    60	            return true;
    61	        }
    62	
    63	        return false;
    64	    }
    65	}
