   133	            throw new OperationNotAllowedException();
   134	        }
   135	
   136	        reservation.setStatus(ReservationStatus.CANCELLED);
   137	
   138	        BigDecimal refund = calculateRefund(reservation);
   139	        reservation.setRefund(refund);
   140	
   141	        reservationRepository.update(reservation);
   142	
   143	        return reservation;
   144	    }
   145	
   146	    private BigDecimal calculateRefund(Reservation reservation) {
   147	        if (reservation.getRatePlan() == RatePlan.STANDARD) {
   148	            return reservation.getAmountPaid();
   149	        }
   150	        return BigDecimal.ZERO;
   151	    }
   152	
   153	    private boolean canTransition(ReservationStatus from, ReservationStatus to) {
   154	        Set<ReservationStatus> allowedTargets = ALLOWED_TRANSITIONS.get(from);
   155	        return allowedTargets != null && allowedTargets.contains(to);
   156	    }
   157	
   158	    public static class InvalidRequestException extends RuntimeException {
   159	    }
   160	
   161	    public static class ReservationNotFoundException extends RuntimeException {
   162	    }
   163	
   164	    public static class RoomUnavailableException extends RuntimeException {
   165	    }
   166	
   167	    public static class CapacityExceededException extends RuntimeException {
   168	    }
   169	
   170	    public static class OperationNotAllowedException extends RuntimeException {
   171	    }
