    14	    private final RoomService roomService;
    15	    private final PriceCalculator priceCalculator;
    16	    private final MessageService messageService;
    17	
    18	    private static final Map<ReservationStatus, Set<ReservationStatus>> ALLOWED_TRANSITIONS = Map.of(
    19	        ReservationStatus.PENDING, Set.of(ReservationStatus.CONFIRMED, ReservationStatus.CANCELLED),
    20	        ReservationStatus.CONFIRMED, Set.of(ReservationStatus.CHECKED_IN, ReservationStatus.CANCELLED),
    21	        ReservationStatus.CHECKED_IN, Set.of(ReservationStatus.CHECKED_OUT)
    22	    );
    23	
    24	    public ReservationService(ReservationRepository reservationRepository,
    25	                              RoomService roomService,
    26	                              PriceCalculator priceCalculator,
    27	                              MessageService messageService) {
    28	        this.reservationRepository = reservationRepository;
    29	        this.roomService = roomService;
    30	        this.priceCalculator = priceCalculator;
    31	        this.messageService = messageService;
    32	    }
    33	
    34	    public Reservation createReservation(int roomNumber, String guestName, String guestEmail, String guestCpf,
    35	                                         LocalDate checkIn, LocalDate checkOut, int guests, RatePlan ratePlan) {
    36	
    37	        if (checkOut.isBefore(checkIn) || checkOut.isEqual(checkIn)) {
    38	            throw new InvalidRequestException();
    39	        }
    40	
    41	        if (guests < 1) {
    42	            throw new InvalidRequestException();
    43	        }
    44	
    45	        Room room = roomService.getRoomByNumber(roomNumber);
    46	
    47	        if (guests > room.getCapacity()) {
    48	            throw new CapacityExceededException();
    49	        }
    50	
    51	        if (reservationRepository.hasConflict(roomNumber, checkIn, checkOut, null)) {
    52	            throw new RoomUnavailableException();
    53	        }
    54	
    55	        int nights = (int) ChronoUnit.DAYS.between(checkIn, checkOut);
    56	        BigDecimal subtotal = priceCalculator.calculateSubtotal(room, checkIn, checkOut);
    57	        BigDecimal discount = priceCalculator.calculateDiscount(subtotal, ratePlan);
    58	        BigDecimal total = priceCalculator.calculateTotal(subtotal, discount);
    59	
    60	        Reservation reservation = new Reservation(
    61	            null,
    62	            roomNumber,
