  1	package com.pousada.repository;
  2	
  3	import com.pousada.config.Database;
  4	import com.pousada.domain.RatePlan;
  5	import com.pousada.domain.Reservation;
  6	import com.pousada.domain.ReservationStatus;
  7	
  8	import java.sql.*;
  9	import java.time.LocalDate;
 10	import java.time.YearMonth;
 11	import java.util.ArrayList;
 12	import java.util.List;
 13	import java.util.Optional;
 14	
 15	public class ReservationRepository {
 16	    private final Database database;
 17	
 18	    public ReservationRepository(Database database) {
 19	        this.database = database;
 20	    }
 21	
 22	    public Reservation save(Reservation reservation) {
 23	        String sql = """
 24	            INSERT INTO reservations (room_number, guest_name, guest_email, guest_cpf,
 25	                                     check_in, check_out, guests, rate_plan, nights,
 26	                                     subtotal, discount, total, status, amount_paid, refund)
 27	            VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
 28	            """;
 29	
 30	        try (Connection conn = database.getConnection();
 31	             PreparedStatement stmt = conn.prepareStatement(sql, Statement.RETURN_GENERATED_KEYS)) {
 32	
 33	            stmt.setInt(1, reservation.getRoomNumber());
 34	            stmt.setString(2, reservation.getGuestName());
 35	            stmt.setString(3, reservation.getGuestEmail());
 36	            stmt.setString(4, reservation.getGuestCpf());
 37	            stmt.setDate(5, Date.valueOf(reservation.getCheckIn()));
 38	            stmt.setDate(6, Date.valueOf(reservation.getCheckOut()));
 39	            stmt.setInt(7, reservation.getGuests());
 40	            stmt.setString(8, reservation.getRatePlan().name());
 41	            stmt.setInt(9, reservation.getNights());
 42	            stmt.setBigDecimal(10, reservation.getSubtotal());
 43	            stmt.setBigDecimal(11, reservation.getDiscount());
 44	            stmt.setBigDecimal(12, reservation.getTotal());
 45	            stmt.setString(13, reservation.getStatus().name());
 46	            stmt.setBigDecimal(14, reservation.getAmountPaid());
 47	            if (reservation.getRefund() != null) {
 48	                stmt.setBigDecimal(15, reservation.getRefund());
 49	            } else {
 50	                stmt.setNull(15, Types.DECIMAL);
 51	            }
 52	
 53	            stmt.executeUpdate();
 54	
 55	            ResultSet keys = stmt.getGeneratedKeys();
 56	            if (keys.next()) {
 57	                reservation.setId(keys.getLong(1));
 58	            }
 59	
 60	            return reservation;
 61	        } catch (SQLException e) {
 62	            throw new RuntimeException("Failed to save reservation", e);
 63	        }
 64	    }
 65	
 66	    public void update(Reservation reservation) {
 67	        String sql = """
 68	            UPDATE reservations
 69	            SET status = ?, amount_paid = ?, refund = ?
 70	            WHERE id = ?
 71	            """;
 72	
 73	        try (Connection conn = database.getConnection();
 74	             PreparedStatement stmt = conn.prepareStatement(sql)) {
 75	
 76	            stmt.setString(1, reservation.getStatus().name());
