     9	import java.math.BigDecimal;
    10	import java.time.LocalDate;
    11	
    12	import static org.junit.jupiter.api.Assertions.assertEquals;
    13	
    14	class PriceCalculatorTest {
    15	
    16	    @Test
    17	    void shouldCalculateStandardPriceInLowSeason() {
    18	        PriceCalculator calculator = new PriceCalculator();
    19	        Room room = new Room(101, RoomType.STANDARD);
    20	
    21	        LocalDate checkIn = LocalDate.of(2027, 3, 10);
    22	        LocalDate checkOut = LocalDate.of(2027, 3, 12);
    23	
    24	        BigDecimal subtotal = calculator.calculateSubtotal(room, checkIn, checkOut);
    25	        BigDecimal discount = calculator.calculateDiscount(subtotal, RatePlan.STANDARD);
    26	        BigDecimal total = calculator.calculateTotal(subtotal, discount);
    27	
    28	        assertEquals(0, new BigDecimal("499.80").compareTo(subtotal));
    29	        assertEquals(0, BigDecimal.ZERO.compareTo(discount));
    30	        assertEquals(0, new BigDecimal("499.80").compareTo(total));
    31	    }
    32	
    33	    @Test
    34	    void shouldCalculateHighSeasonPrice() {
    35	        PriceCalculator calculator = new PriceCalculator();
    36	        Room room = new Room(101, RoomType.STANDARD);
    37	
    38	        LocalDate checkIn = LocalDate.of(2027, 7, 10);
    39	        LocalDate checkOut = LocalDate.of(2027, 7, 12);
